import Component from 'flarum/common/Component';
import app from 'flarum/admin/app';
import { joinColor, splitColor } from '../utils/color';
/** A color with its opacity, as `#rrggbbaa`. */
export default class AlphaColorInput extends Component {
  view() {
    const {
      value,
      onchange,
      label
    } = this.attrs;
    const {
      rgb,
      opacity
    } = splitColor(value);
    return m("div", {
      className: "wch-AlphaColor"
    }, m("input", {
      type: "color",
      className: "wch-AlphaColor-color",
      value: rgb,
      "aria-label": label,
      oninput: e => onchange(joinColor(e.target.value, opacity))
    }), m("input", {
      type: "range",
      className: "wch-AlphaColor-opacity",
      min: "0",
      max: "100",
      value: opacity,
      "aria-label": app.translator.trans('walsgit-custom-heroes.admin.overlay.opacity_label', {
        label
      }, true),
      oninput: e => onchange(joinColor(rgb, Number(e.target.value)))
    }), m("span", {
      className: "wch-AlphaColor-value"
    }, opacity, "%"));
  }
}
flarum.reg.add('walsgit-custom-heroes', 'admin/components/AlphaColorInput', AlphaColorInput);